window.Prep=(()=>{
 let state={durationHours:48,startLocal:'',deliveryMode:'online',scoringPreset:60,done:{}},loaded=false,loading=true,error='',saving=false,pending={},todoFilter='open';
 let expanded=true;try{const preference=localStorage.getItem('hackathon-timeline-expanded');expanded=preference===null?!matchMedia('(max-width:800px)').matches:preference==='true'}catch(e){}
 const titles=Object.fromEntries(window.PREP_NAV.flatMap(g=>g.chapters));
 const deliveryLabels={online:'线上',onsite:'线下',hybrid:'混合'};
 const esc=s=>escapeHTML(s),now=()=>Date.now();
 const dateText=t=>t===null?'待设置开赛时间':new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(t);
 const relative=h=>h===0?'T0':(h<0?'T−':'T+')+(Math.abs(h)>=24&&Number.isInteger(h/24)?Math.abs(h/24)+'天':Number(Math.abs(h).toFixed(2))+'h');
 function schedule(){return PrepMath.calculate(state,planConfig)}
 function tasks(){return window.PREP_TASKS.filter(t=>(t.when!=='final'||planConfig.teams>30)&&(t.when!=='onsite'||state.deliveryMode!=='online'))}
 function stats(chapter){const items=tasks().filter(t=>!chapter||t.chapter===chapter),s=schedule();return {total:items.length,done:items.filter(t=>state.done[t.id]===true).length,overdue:items.filter(t=>!state.done[t.id]&&PrepMath.due(t,s)!==null&&PrepMath.due(t,s)<now()).length}}
 function groupStats(id){const group=window.PREP_NAV.find(g=>g.id===id),ids=new Set(group.chapters.map(c=>c[0])),items=tasks().filter(t=>ids.has(t.chapter)),s=schedule();return {total:items.length,done:items.filter(t=>state.done[t.id]===true).length,overdue:items.filter(t=>!state.done[t.id]&&PrepMath.due(t,s)!==null&&PrepMath.due(t,s)<now()).length}}
 function countdown(){const s=schedule();if(s.start===null)return {value:'待设置',label:'预计开赛时间'};let target=s.start,label='距离开赛';if(target<=now()){const next=s.milestones.find(m=>m.time>now());if(!next)return {value:'已到回顾期',label:'仍可完成未勾选任务'};target=next.time;label='距离'+next.label}const minutes=Math.max(0,Math.ceil((target-now())/60000)),days=Math.floor(minutes/1440),hours=Math.floor(minutes%1440/60),mins=minutes%60;return {value:days>0?days+'天 '+hours+'小时':hours+'小时 '+mins+'分钟',label}}
 function canConfigure(){return loaded||PlanStore.mode==='guest'}
 function statusHTML(){if(loading)return '正在读取账户计划…';if(PlanStore.mode==='guest')return '访客试用 · 调整仅在当前页面生效 <a class="text-btn" href="/signin-with-chatgpt?return_to=%2F" target="_top">登录并保存个人计划</a>';if(!loaded)return '<span class="error">'+esc(error||'读取失败')+'</span> <button class="text-btn" data-retry-load>重试读取</button>';if(error)return '<span class="error">'+esc(error)+'</span> <button class="text-btn" data-retry-save>重试保存</button>';return saving?'正在保存…':PlanStore.mode==='preview'?'本地预览数据已保存；正式网站按账户保存':'计划与进度已自动保存到账户'}
 function controlsHTML(){return '<div class="prep-controls"><label class="start-field">预计开赛日期与时刻 <span class="caption">北京时间 UTC+8</span><input type="datetime-local" data-start value="'+esc(state.startLocal)+'" '+(!canConfigure()?'disabled':'')+'></label><div><span class="control-label">制作周期</span><div class="duration-options">'+[24,48,72,96].map(h=>'<button data-duration="'+h+'" aria-pressed="'+(h===state.durationHours)+'" class="'+(h===state.durationHours?'active':'')+'" '+(!canConfigure()?'disabled':'')+'>'+h+'h</button>').join('')+'</div></div></div>'}
 function timelineHTML(){const items=PrepMath.phases(schedule(),now());return '<ol class="prep-timeline" aria-label="活动阶段">'+items.map((m,i)=>'<li class="prep-milestone '+m.state+'" '+(m.state==='current'?'aria-current="step"':'')+'><span class="milestone-dot">'+String(i+1).padStart(2,'0')+'</span><strong>'+m.label+'</strong><time>'+ (i===0?'先完成规则与资源':dateText(m.time))+'</time><small>'+(i===0?'报名前准备':relative(m.offset))+'</small><span class="milestone-state">'+m.status+'</span></li>').join('')+'</ol>'}
 function modeText(){return deliveryLabels[state.deliveryMode]+' · '+state.durationHours+'h · '+planConfig.teams+' 队 · '+(planConfig.teams>30?'海选＋决赛':'单轮')+' · '+(state.startLocal?dateText(PrepMath.parseStart(state.startLocal))+' 开赛':'待设置开赛时间')}
 function summaryHTML(){const st=stats(),c=countdown();return '<span class="plan-countdown">'+c.label+' <strong>'+c.value+'</strong></span><span class="plan-completion">已完成 <strong>'+st.done+'/'+st.total+'</strong><span class="summary-progress" role="progressbar" aria-label="筹备完成进度" aria-valuemin="0" aria-valuemax="'+st.total+'" aria-valuenow="'+st.done+'"><i style="width:'+100*st.done/st.total+'%"></i></span></span><a class="plan-pending" href="#overview">'+(st.total-st.done)+' 项待办'+(st.overdue?' · '+st.overdue+' 项已到期':'')+'</a><button class="btn plan-export-trigger" data-generate-plan '+(!canConfigure()?'disabled':'')+'>'+((st.done===st.total&&st.total>0&&state.startLocal&&loaded)?'生成完整方案':'生成方案')+'</button>'}
 function globalHTML(){return '<div class="plan-bar"><div class="plan-identity"><span class="mark">H</span><div><h2>筹备黑客松指北</h2><span class="plan-mode">'+modeText()+'</span></div></div><div class="plan-summary" data-plan-summary>'+summaryHTML()+'</div><button class="plan-toggle" data-plan-toggle aria-expanded="'+expanded+'" aria-controls="plan-settings">'+(expanded?'收起总轴':'展开总轴')+'<span aria-hidden="true">'+(expanded?'−':'+')+'</span></button></div><div id="plan-settings" class="plan-settings" '+(expanded?'':'hidden')+'>'+controlsHTML()+'<div class="global-team summary-team">'+deliveryHTML()+'<span>当前活动方案</span><strong>'+planConfig.teams+' 队 · '+ScoreRules.profile(state.scoringPreset).ratio+'</strong><span class="caption">在下方看板调整队伍规模与评分</span></div></div><div id="prep-timeline">'+timelineHTML()+'</div><div class="plan-foot"><p>灰色节点尚未到达；时间进度不代表待办已完成。</p><div class="save-status" data-save-status role="status">'+statusHTML()+'</div></div>'}
 function deliveryHTML(){return '<label class="delivery-field">活动形式<select data-delivery '+(!canConfigure()?'disabled':'')+'>'+Object.entries(deliveryLabels).map(([value,label])=>'<option value="'+value+'" '+(state.deliveryMode===value?'selected':'')+'>'+label+'</option>').join('')+'</select></label>'}
 function dashboardHTML(){return '<section class="panel"><div class="section-label"><h2>全部筹备待办</h2><div class="todo-filters"><button data-filter="open" class="'+(todoFilter==='open'?'active':'')+'">未完成</button><button data-filter="all" class="'+(todoFilter==='all'?'active':'')+'">全部</button></div></div><p class="caption">覆盖左侧六个模块，勾选你已核实完成的事项。线上模式不计入现场餐饮与场地任务；切换形式保留已勾选记录。</p><div id="todo-list">'+todoHTML()+'</div></section>'}
 function paintGlobal(){const root=document.querySelector('#global-plan');if(!root)return;root.classList.toggle('is-collapsed',!expanded);const st=root.querySelector('[data-plan-summary]');if(st)st.innerHTML=summaryHTML();const mode=root.querySelector('.plan-mode');if(mode)mode.textContent=modeText();document.documentElement.style.setProperty('--plan-height',root.offsetHeight+'px')}
 function taskHTML(task){const done=state.done[task.id]===true,s=schedule(),due=PrepMath.due(task,s),overdue=!done&&due!==null&&due<now();return '<label class="todo-row '+(done?'done':'')+'"><input type="checkbox" data-task="'+task.id+'" '+(done?'checked':'')+' '+(!loaded?'disabled':'')+'><span><strong>'+esc(task.label)+'</strong><small>'+esc(titles[task.chapter])+' · '+(task.anchor==='AWARD'?'发放日期按已发布的奖项公告':due===null?'建议 '+relative(s.anchors[task.anchor]+task.hours):'建议截止 '+dateText(due))+(overdue?' <em>已到期 · 待补办</em>':'')+'</small></span></label>'}
 function todoHTML(){const all=tasks().filter(t=>todoFilter==='all'||!state.done[t.id]);if(all.length===0)return '<div class="note">当前适用的任务均已勾选完成。仍需按实际情况复核奖项与作品维护。</div>';return Object.entries(titles).map(([id,label])=>{const arr=all.filter(t=>t.chapter===id);if(!arr.length)return '';const s=stats(id),group=window.PREP_NAV.find(g=>g.chapters.some(c=>c[0]===id));return '<details class="todo-group" data-chapter="'+id+'" '+(s.overdue>0||id==='overview'?'open':'')+'><summary><span>'+esc(group.title)+' / '+esc(label)+'</span><span class="caption">'+s.done+'/'+s.total+' 完成 · '+(s.total-s.done)+' 待办</span></summary><div>'+arr.map(taskHTML).join('')+'<a class="task-rule-link" href="#'+id+'">查看本章规则</a></div></details>'}).join('')}
 function chapterHTML(chapter){const arr=tasks().filter(t=>t.chapter===chapter),s=stats(chapter);if(!arr.length)return '<section class="panel chapter-tasks"><span class="kicker">'+esc(titles[chapter])+'</span><h2>当前为线上活动</h2><p>本章现场待办暂不计入总进度，筹备参考仍可浏览。若有集中到场环节，请在下方或顶部选择线下／混合。</p>'+deliveryHTML()+'</section>';return '<section class="panel chapter-tasks task-board"><div class="section-label"><div><span class="kicker">'+esc(titles[chapter])+'</span><h2>本章节待办任务</h2></div><div class="task-board-actions"><span class="badge" data-chapter-stat="'+chapter+'">'+s.done+'/'+s.total+' 已完成</span><button class="task-scroll" data-task-scroll="-1" aria-label="向前浏览待办">‹</button><button class="task-scroll" data-task-scroll="1" aria-label="向后浏览待办">›</button></div></div><div class="chapter-task-strip" tabindex="0" role="region" aria-label="本章待办，可横向滑动">'+arr.map(taskHTML).join('')+'</div><div class="task-board-foot"><span class="caption">横向滑动浏览 · 核实完成后勾选</span><div class="save-status" data-save-status>'+statusHTML()+'</div></div></section>'}
 function journeyScheduleHTML(){const s=schedule();return '<div class="note">当前计划：'+state.durationHours+'小时制作，'+planConfig.teams+'队，'+(s.plan.hasFinal?'海选后默认12队决赛':'全员一轮完成')+'。在顶部展开总轴调整计划，中途检查、预检、提交及后续评审日期同步变化。</div>'+table(['节点','相对开赛','预计时间（UTC+8）'],s.milestones.map(m=>[m.label,relative(m.offset),dateText(m.time)]))+'<p class="caption">制作周期只决定创作时段。资格审核12h、异步阅件/互评72h另计；路演还需预留抽签通知及必要申诉窗口。这里不自动改动主办方真实会议或日历。</p><div data-save-status class="save-status">'+statusHTML()+'</div>'}
 function decorateNavigation(){document.querySelectorAll('[data-group-progress]').forEach(el=>{const s=groupStats(el.dataset.groupProgress);el.textContent=s.total?s.done+'/'+s.total:'线下适用'});document.querySelectorAll('#nav a').forEach(a=>{a.querySelector('.nav-progress')?.remove();const s=stats(a.getAttribute('href').slice(1));const el=document.createElement('span');el.className='nav-progress'+(s.total>0&&s.done===s.total?' complete':'');el.textContent=s.total?s.done+'/'+s.total:'参考';el.setAttribute('aria-label','已完成'+s.done+'项，共'+s.total+'项');a.appendChild(el)})}
 function bindTasks(){document.querySelectorAll('[data-task]').forEach(input=>{input.onchange=()=>{const id=input.dataset.task;state.done[id]=input.checked;save({done:{[id]:input.checked}});paintProgress()}})}
 function bindRetry(){document.querySelectorAll('[data-retry-load]').forEach(b=>b.onclick=init);document.querySelectorAll('[data-retry-save]').forEach(b=>b.onclick=()=>{error='';pump()})}
 function paintStatus(){document.querySelectorAll('[data-save-status]').forEach(el=>el.innerHTML=statusHTML());bindRetry()}
 function paintProgress(){paintGlobal();document.querySelectorAll('[data-module]').forEach(el=>{const s=groupStats(el.dataset.module),values={done:s.done,pending:s.total-s.done,overdue:s.overdue};el.querySelectorAll('[data-module-count]').forEach(n=>n.textContent=values[n.dataset.moduleCount])});const st=stats(),c=countdown();[['#done-count',st.done+' / '+st.total],['#pending-count',(st.total-st.done)+' 项'],['#overdue-count',st.overdue+' 项'],['#countdown-label',c.label],['#countdown-value',c.value]].forEach(([sel,value])=>{const el=document.querySelector(sel);if(el)el.textContent=value});const timeline=document.querySelector('#prep-timeline');if(timeline)timeline.innerHTML=timelineHTML();const todos=document.querySelector('#todo-list');if(todos){const openState=new Map(Array.from(todos.querySelectorAll('.todo-group')).map(el=>[el.dataset.chapter,el.open]));todos.innerHTML=todoHTML();todos.querySelectorAll('.todo-group').forEach(el=>{if(openState.has(el.dataset.chapter))el.open=openState.get(el.dataset.chapter)})}document.querySelectorAll('[data-chapter-stat]').forEach(el=>{const s=stats(el.dataset.chapterStat);el.textContent=s.done+'/'+s.total+' 已完成'});document.querySelectorAll('[data-task]').forEach(input=>{input.checked=state.done[input.dataset.task]===true;input.closest('.todo-row').classList.toggle('done',input.checked);const task=tasks().find(t=>t.id===input.dataset.task);if(task){const wrap=document.createElement('div');wrap.innerHTML=taskHTML(task);input.closest('.todo-row').querySelector('small').innerHTML=wrap.querySelector('small').innerHTML}});decorateNavigation();bindTasks();paintStatus()}
 function merge(a,b){const result={...a,...b};if(a.plan||b.plan)result.plan={...a.plan,...b.plan};if(a.done||b.done)result.done={...a.done,...b.done};return result}
 function save(patch){if(!loaded)return;pending=merge(pending,patch);error='';pump()}
 async function pump(){if(saving||Object.keys(pending).length===0)return;const patch=pending;pending={};saving=true;paintStatus();try{await PlanStore.patch(patch);error=''}catch(e){pending=merge(patch,pending);error=e.message||'保存失败，当前改动仍在本页'}finally{saving=false;paintStatus()}if(!error&&Object.keys(pending).length)pump()}
 async function init(){loading=true;error='';paintStatus();try{const data=await PlanStore.load();if(data===null){loaded=false;loading=false;render();return}if(['online','onsite','hybrid'].includes(data.deliveryMode))state.deliveryMode=data.deliveryMode;if([60,70,50].includes(data.scoringPreset))state.scoringPreset=data.scoringPreset;if([24,48,72,96].includes(data.durationHours))state.durationHours=data.durationHours;if(typeof data.startLocal==='string'){PrepMath.parseStart(data.startLocal);state.startLocal=data.startLocal}state.done={};for(const t of window.PREP_TASKS)if(data.done?.[t.id]===true)state.done[t.id]=true;if(data.plan){HackathonPlanner.validate({...planConfig,...data.plan});planConfig={...planConfig,...data.plan}}loaded=true;loading=false;render()}catch(e){loading=false;error=e.message||'无法读取账户进度';paintStatus()}}
 function onRendered(){paintGlobal();document.querySelectorAll('[data-delivery]').forEach(el=>el.onchange=()=>{state.deliveryMode=el.value;save({deliveryMode:state.deliveryMode});render()});document.querySelectorAll('[data-task-scroll]').forEach(b=>b.onclick=()=>{const strip=document.querySelector('.chapter-task-strip');strip.scrollBy({left:Number(b.dataset.taskScroll)*Math.min(strip.clientWidth,320),behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'})});document.querySelector('[data-plan-toggle]')?.addEventListener('click',()=>{expanded=!expanded;try{localStorage.setItem('hackathon-timeline-expanded',String(expanded))}catch(e){}const button=document.querySelector('[data-plan-toggle]');button.setAttribute('aria-expanded',String(expanded));button.innerHTML=(expanded?'收起总轴':'展开总轴')+'<span aria-hidden="true">'+(expanded?'−':'+')+'</span>';document.querySelector('#plan-settings').hidden=!expanded;paintGlobal()});decorateNavigation();bindTasks();bindRetry();document.querySelectorAll('[data-duration]').forEach(b=>b.onclick=()=>{state.durationHours=+b.dataset.duration;save({durationHours:state.durationHours});render()});document.querySelectorAll('[data-start]').forEach(input=>input.onchange=()=>{try{input.setCustomValidity('');PrepMath.parseStart(input.value);state.startLocal=input.value;save({startLocal:state.startLocal});render()}catch(e){input.setCustomValidity(e.message);input.reportValidity()}});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{todoFilter=b.dataset.filter;render()});if(!canConfigure())document.querySelectorAll('[data-plan],[data-teams],[data-scoring-preset],[data-copy],[data-download],[data-download-all]').forEach(el=>el.disabled=true)}
 function planChanged(){save({plan:{...planConfig}});paintProgress();paintGlobal()}
 const topObserver=new ResizeObserver(()=>{const el=document.querySelector('#global-plan');if(el)document.documentElement.style.setProperty('--plan-height',el.offsetHeight+'px')});topObserver.observe(document.querySelector('#global-plan'));
 setInterval(paintProgress,60000);
 async function flush(){while(saving)await new Promise(r=>setTimeout(r,30));if(error||Object.keys(pending).length)throw Error(error||'计划尚未保存')}
 async function setTasks(changes){if(!loaded)throw Error('账户计划尚未加载');if(!Array.isArray(changes)||changes.length===0||changes.length>window.PREP_TASKS.length)throw Error('请提供1–'+window.PREP_TASKS.length+'项任务');const active=tasks();for(const c of changes)if(!c||!active.some(t=>t.id===c.id)||typeof c.completed!=='boolean')throw Error('任务ID无效或此任务当前不适用');const patch={};for(const c of changes){state.done[c.id]=c.completed;patch[c.id]=c.completed}save({done:patch});paintProgress();await flush();return {...stats(),saved:true}}
 return {flush,setTasks,tasks,groupStats,deliveryHTML,canConfigure,getScoring:()=>state.scoringPreset,setScoring:async value=>{if(!canConfigure())throw Error('账户计划尚未加载');ScoreRules.validate(value);state.scoringPreset=value;save({scoringPreset:value});render();await flush();return {scoringPreset:value,saved:loaded}},isLoaded:()=>loaded,globalHTML,dashboardHTML,chapterHTML,journeyScheduleHTML,onRendered,init,planChanged,stats,getSettings:()=>({durationHours:state.durationHours,startLocal:state.startLocal,deliveryMode:state.deliveryMode,scoringPreset:state.scoringPreset,done:{...state.done}}),setSchedule:async function(input){if(!canConfigure())throw Error('账户计划尚未加载');if(input.deliveryMode!==undefined&&!['online','onsite','hybrid'].includes(input.deliveryMode))throw Error('无效活动形式');if(input.durationHours!==undefined&&![24,48,72,96].includes(input.durationHours))throw Error('无效周期');if(input.startLocal!==undefined)PrepMath.parseStart(input.startLocal);if(input.deliveryMode!==undefined)state.deliveryMode=input.deliveryMode;if(input.durationHours!==undefined)state.durationHours=input.durationHours;if(input.startLocal!==undefined)state.startLocal=input.startLocal;save({durationHours:state.durationHours,startLocal:state.startLocal,deliveryMode:state.deliveryMode});render();await flush();return {durationHours:state.durationHours,startLocal:state.startLocal,deliveryMode:state.deliveryMode,saveStatus:!loaded?'guest':saving?'saving':error?'error':'saved'}}};
})();
